mapper.select:
SELECT to_char(ended_at AT TIME ZONE #{query.Timezone}, 'YYYY-MM-DD') AS day,
model, workspace_uuid, source, COALESCE(CAST(api_key_uuid AS text), '') AS api_key_uuid,
COUNT(*) AS requests,
CAST(COALESCE(SUM(input_tokens), 0) AS bigint) AS input_tokens,
CAST(COALESCE(SUM(output_tokens), 0) AS bigint) AS output_tokens,
CAST(COALESCE(SUM(cache_read_tokens), 0) AS bigint) AS cache_read_tokens,
CAST(COALESCE(SUM(cache_write_tokens), 0) AS bigint) AS cache_write_tokens,
CAST(COALESCE(SUM(cache_write_5m_tokens), 0) AS bigint) AS cache_write_5m_tokens,
CAST(COALESCE(SUM(cache_write_1h_tokens), 0) AS bigint) AS cache_write_1h_tokens,
CAST(COALESCE(SUM(search_requests), 0) AS bigint) AS search_requests,
CAST(COALESCE(SUM(model_cents), 0) AS bigint) AS model_cents,
CAST(COALESCE(SUM(search_cents), 0) AS bigint) AS search_cents,
COUNT(*) FILTER (WHERE model_cents IS NULL) AS unpriced,
COUNT(*) FILTER (WHERE NOT complete) AS incomplete
FROM usage_records
WHERE organization_uuid = #{query.OrganizationUUID}
AND workspace_uuid IN #{workspace}
AND ended_at >= #{query.Start} AND ended_at < #{query.End}
AND recorded_at <= #{query.AsOf}
AND finalized
AND model = #{query.Model}
AND source = #{query.Source}
AND session_external_id = #{query.SessionID}
AND api_key_uuid = #{query.APIKeyUUID}
GROUP BY 1, 2, 3, 4, 5
ORDER BY 1, 2, 3, 4, 5

SELECT to_char(ended_at AT TIME ZONE #{query.Timezone}, 'YYYY-MM-DD') AS day,
model,
price_snapshot,
input_tokens, output_tokens, cache_read_tokens, cache_write_tokens,
cache_write_5m_tokens, cache_write_1h_tokens,
COALESCE(model_cents, 0) AS model_cents,
COALESCE(model_cost_usd, '') AS model_cost_usd
FROM usage_records
WHERE organization_uuid = #{query.OrganizationUUID}
AND workspace_uuid IN #{workspace}
AND ended_at >= #{query.Start} AND ended_at < #{query.End}
AND recorded_at <= #{query.AsOf}
AND finalized
AND price_snapshot IS NOT NULL
AND model = #{query.Model}
AND source = #{query.Source}
AND session_external_id = #{query.SessionID}
AND api_key_uuid = #{query.APIKeyUUID}
ORDER BY ended_at

SELECT model, COALESCE(CAST(api_key_uuid AS text), '') AS api_key_uuid, MIN(ended_at) AS first_seen
FROM usage_records
WHERE organization_uuid = #{query.OrganizationUUID}
AND workspace_uuid IN #{workspace}
AND finalized
GROUP BY model, api_key_uuid ORDER BY model, api_key_uuid
